seed = [[9,9,9,9,1,5],[9,6,4,9,9,5],[5,9,9,6,9,9],[9,1,9,4,9,9],[9,9,9,6,9,9],[5,4,9,4,1,9],[9,5,4,1,4,5],[1,9,9,6,9,9],[9,9,9,9,6,9]]
# compose 29x20 with divider rows 9,19 and cols 6,13
out=[]
for r in range(29):
    row=[]
    for c in range(20):
        if r in (9,19) or c in (6,13): row.append(2)
        else:
            rr=r if r<9 else (r-10 if r<19 else r-20)
            cc=c if c<6 else (c-7 if c<13 else c-14)
            row.append(seed[rr][cc])
    out.append(row)
print(out)
